/* eslint-disable no-unused-vars */
import React, { useEffect, useRef, useState } from 'react';
import './App.css';
import { Stages } from './Stages';

export function Main() {
  const [selectedAnswer, setSelectedAnswer] = useState(null);
  const [radioSymbol, setRadioSymbol] = useState([]);
  const [questions, setQuestions] = useState([]);
  const [shuffledAnswers, setShuffledAnswers] = useState([]);
  const [stageCounter, setStageCounter] = useState(0);

  const videoRef = useRef(null);

  useEffect(() => {
    fetchQuestionsAndAnswers();
    if (videoRef.current) {
      const video = videoRef.current;
      video.play();
      setTimeout(() => {
        video.classList.add('remove');
      }, 2000);
    }
  }, []);

  const fetchQuestionsAndAnswers = async () => {
    try {
      const response = await fetch('/home');
      const data = await response.json();
      setQuestions(data.questions);
      shuffleAnswers(data.questions[stageCounter]); // Shuffling answers for the first question
    } catch (error) {
      console.error('Error fetching data:', error);
    }
  };

  const shuffleAnswers = (questionData) => {
    if (questionData) {
      const { wrong, right } = questionData;
      const allAnswers = [...wrong, right];
  
      // Shuffle all answers
      for (let i = allAnswers.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [allAnswers[i], allAnswers[j]] = [allAnswers[j], allAnswers[i]];
      }
  
      setShuffledAnswers(allAnswers);
      setRadioSymbol(Array(allAnswers.length).fill('◇'));
    }
  };

  const handleAnswerClick = (event, index) => {
    const selectedDiv = event.currentTarget;

    const answerDivs = document.querySelectorAll('.answer');
    answerDivs.forEach(div => {
      div.classList.remove('selected');
    });

    selectedDiv.classList.add('selected');

    const newRadioSymbols = Array(shuffledAnswers.length).fill('◇');
    newRadioSymbols[index] = '◈';
    setRadioSymbol(newRadioSymbols);

    const radioButton = selectedDiv.querySelector('input[type="radio"]');
    if (radioButton) {
      radioButton.checked = true;
      setSelectedAnswer(radioButton.id);
    }
  };

  const [gameInProgress, setGameInProgress] = useState(true); // State to track game progress

  const handleQuitClick = () => {
    fetch('/quit-game', { method: 'GET' })
      .then(response => response.json())
      .then(data => {
        if (data.confirmationRequired) {
          // Show confirmation dialog to the user
          // You can handle this on the client side
          // For example, by setting a state to show a confirmation modal
          // Or triggering a browser's native confirmation dialog
          // Based on the user's choice, you can take further action
          // For now, let's assume the user confirmed to quit
          handleQuitConfirmation(true);
        } else {
          // End the game session immediately
          // Reset session data as needed
          setGameInProgress(false); // Resetting the game in progress for demonstration
          setStageCounter(0); // Resetting the stage for demonstration
        }
      })
      .catch(error => {
        // Handle error
      });
  };

  const handleQuitConfirmation = (confirmed) => {
    if (confirmed) {
      // Perform actions for confirmed quit
      // For demonstration, resetting the game in progress and stageCounter to initial
      setGameInProgress(false);
      setStageCounter(0);
    }
    // Hide or handle confirmation dialog on the client side
  };

  useEffect(() => {
    const handleBeforeUnload = (event) => {
      event.preventDefault();
      event.returnValue = '';

      // Check if the game is in progress
      // Trigger confirmation if the game is in progress
      if (gameInProgress) {
        event.returnValue = 'Do you want to quit the game?';
        return 'Do you want to quit the game?';
      }
    };

    window.addEventListener('beforeunload', handleBeforeUnload);

    return () => {
      window.removeEventListener('beforeunload', handleBeforeUnload);
    };
  }, [gameInProgress]);

  return (
    <div className="bkgr" id="bkgr3">
      <video className="video" ref={videoRef} id="open_curt" autoPlay muted>
        <source src="/Img/open_curt.webm" type="video/webm" />
      </video>
      <Stages stagePass={stageCounter} />
      <form className="main_game" id="game_continue">
        <div className="question">{questions.length > 0 ? questions[stageCounter].question : ''}</div>
        <div className="answer_cont">
          <fieldset>
            {shuffledAnswers.map((answer, index) => (
              <div
                className={`answer ${radioSymbol[index] === '◈' ? 'selected' : ''}`}
                key={`answer_${index}`}
                onClick={(event) => handleAnswerClick(event, index)}
              >
                <span className="answer_letter">{radioSymbol[index]}</span>
                <input type="radio" id={`Answer_${index}`} name="answers"></input>
                <label htmlFor={`Answer_${index}`}>{answer}</label>
              </div>
            ))}
          </fieldset>
        </div>
        <div className="line2"></div>
        <div className="option_cont">
        <div className="check_btn" onClick={handleQuitClick}>Quit game</div>
          <div className="help_cont">
            <div className="help" id="fifty"></div>
            <div className="help used" id="people"></div>
            <div className="help" id="refresh"></div>
          </div>
          <input type='submit' className="check_btn" value="Submit answer"></input>
        </div>
        <div className="line2"></div>
      </form>
    </div>
  );
}
